fn is_non_prime(n: u64) -> bool {
    // Assumption from the problem statement: n >= 2
    if n <= 3 {
        return false; // 2 and 3 are prime; also matches "no k in [2, n-1]" for n=2
    }

    // Check for a divisor k in [2, n-1].
    // It's sufficient to check up to floor(sqrt(n)):
    // if n has a non-trivial divisor, one exists <= sqrt(n).
    let mut k: u64 = 2;
    while k <= n / k {
        if n % k == 0 {
            return true;
        }
        k += 1;
    }

    false
}